using System;using System.IO;using System.Reflection;using System.Text;using UnityEditor;using UnityEngine;using UnityEngine.UIElements;
namespace ZeroToMillionaire.Editor {
 [InitializeOnLoad]public static class DialogueEntranceAuditV08 {
 const string Key="ZTM_DIALOGUE_ENTRANCE_V08";static GameView view;static RenderTexture target;static int phase,scenario,checks;static double started;static float at;static string tag=>SessionState.GetString(Key+"tag","missing");static StringBuilder log=new StringBuilder();
 static string Root=>Directory.GetParent(Application.dataPath).FullName;static VisualElement UI=>view.GetComponent<UIDocument>().rootVisualElement;static VisualElement Bubble=>UI.Q<VisualElement>("heroine-dialogue");
 static DialogueEntranceAuditV08(){EditorApplication.update+=Tick;}
 public static void BatchStart(){SessionState.SetString(Key+"tag",Environment.GetEnvironmentVariable("ZTM_ENTRANCE_TAG")??"after1");if(!System.Text.RegularExpressions.Regex.IsMatch(tag,"^[a-z0-9-]+$"))throw new Exception("Scoped tag required");if(File.Exists(Path.Combine(Root,"Evidence","v08-entrance-"+tag+".txt")))throw new Exception("Immutable report exists");Environment.SetEnvironmentVariable("ZTM_QA_SAVE_DIR",Path.Combine(Root,".tooling","v08-entrance-"+tag,"save"));UnityEditor.SceneManagement.EditorSceneManager.OpenScene("Assets/Scenes/Level1.unity");SessionState.SetBool(Key,true);EditorApplication.EnterPlaymode();}
 static void At(int p){phase=p;at=Time.unscaledTime;}
 static void Check(bool ok,string message){log.AppendLine((ok?"PASS ":"FAIL ")+message);if(!ok)throw new Exception(message);checks++;}
 static void Capture(string name){var previous=RenderTexture.active;RenderTexture.active=target;var texture=new Texture2D(target.width,target.height,TextureFormat.RGBA32,false);texture.ReadPixels(new Rect(0,0,target.width,target.height),0,0);texture.Apply();File.WriteAllBytes(Path.Combine(Root,"Evidence","v08-entrance-"+tag+"-"+name+".png"),texture.EncodeToPNG());UnityEngine.Object.Destroy(texture);RenderTexture.active=previous;}
 static void Tick(){if(!SessionState.GetBool(Key,false)||!EditorApplication.isPlaying)return;try{if(started==0)started=EditorApplication.timeSinceStartup;if(EditorApplication.timeSinceStartup-started>45)throw new Exception("Bounded entrance audit timeout phase="+phase);if(view==null){view=UnityEngine.Object.FindFirstObjectByType<GameView>();if(view==null||view.Model==null)return;}
 if(phase==0){target=new RenderTexture(360,640,0,RenderTextureFormat.ARGB32);target.Create();view.GetComponent<UIDocument>().panelSettings.targetTexture=target;At(1);}
 else if(phase==1&&Time.unscaledTime-at>.3f){var state=new PlayerState{cash=1000};state.tutorial.completed=true;state.tutorial.storySeenMask=15;view.SetQaState(state,0);view.QaClick("menu");At(2);}
 else if(phase==2&&Time.unscaledTime-at>.3f){bool calm=scenario>=2;var presentation=(PresentationPreferences)typeof(GameView).GetField("presentation",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(view);if(presentation.ReducedMotion!=calm)view.QaClick("motion-toggle");view.QaClick("tutorial-replay");Check(Bubble.style.display==DisplayStyle.Flex,"scenario "+scenario+" replay begins visible calm="+calm);Check(calm||Bubble.style.opacity.value<.1f,"new entrance is animated only in full mode");if(scenario%2==0)view.QaClick("menu");else view.QaClick("spin");At(3);}
 else if(phase==3&&Time.unscaledTime-at>.20f){Check(Bubble.style.display==DisplayStyle.None,"interrupted replay is hidden");if(scenario%2==0)view.QaClick("close-settings");At(4);}
 else if(phase==4&&!view.QaSpinning&&Time.unscaledTime-at>2.8f){Check(Bubble.style.display==DisplayStyle.Flex,"same replay mode resumes visible");float opacity=Bubble.resolvedStyle.opacity;float translation=Bubble.resolvedStyle.translate.y;log.AppendLine("OBSERVED scenario="+scenario+" opacity="+opacity+" translationY="+translation+" runtime="+Time.unscaledTime);Capture("scenario-"+scenario);Check(opacity>.999f&&Mathf.Abs(translation)<.01f,"resumed dialogue is fully opaque and settled");Check(view.Model.Snapshot.spins==(scenario%2==0?0:1),"interruption does not create extra spin awards");view.QaClick("tutorial-skip");scenario++;if(scenario<4)At(1);else{log.AppendLine("RESULT PASS checks="+checks+"; actual graphics Editor/UI events; full/calm MENU/SPIN entrance interruption; private save; no OS input");Finish();}}
 }catch(Exception e){log.AppendLine("RESULT FAIL phase="+phase+" scenario="+scenario+" "+e);Debug.LogException(e);Finish();}}
 static void Finish(){SessionState.SetBool(Key,false);File.WriteAllText(Path.Combine(Root,"Evidence","v08-entrance-"+tag+".txt"),log.ToString());if(target!=null){view.GetComponent<UIDocument>().panelSettings.targetTexture=null;target.Release();UnityEngine.Object.Destroy(target);}EditorApplication.ExitPlaymode();if(SessionState.GetBool(Key+"exit",false))EditorApplication.delayCall+=()=>EditorApplication.Exit(0);}
 }
}
